    def matrix_mult(A, B):
        mod_val = mod
        n1 = len(A)
        p = len(A[0])
        m1 = len(B[0])
        C = [[0] * m1 for _ in range(n1)]
        for i in range(n1):
            for k in range(p):
                a_ik = A[i][k]
                if a_ik != 0:
                    for j in range(m1):
                        C[i][j] = (C[i][j] + a_ik * B[k][j]) % mod_val
        return C

    def matrix_power(matrix, power):
        mod_val = mod
        n_val = len(matrix)
        result = [[0] * n_val for _ in range(n_val)]
        for i in range(n_val):
            result[i][i] = 1

        base = matrix
        while power:
            if power & 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            power //= 2
        return result

